# =============================================================================
# Shiny app - mGFR with iohexol and eGFR (EKFC, CKD-EPI 2021)
# Local start (no RStudio needed):  Rscript -e 'shiny::runApp("en", port = 3838)'
# Deployment on Shiny Server: see the deploy/ folder in the repository root
# Required packages: shiny, bslib (>= 0.5), rmarkdown, knitr
# The HTML report is generated by rmarkdown, which requires pandoc
# =============================================================================
library(shiny)
library(bslib)

# If the server runs with a non-UTF-8 locale (e.g. LANG=C), symbols such as
# µ, ² and ≥ in the report would become "<U+00B5>": switch to a UTF-8 locale
if (!isTRUE(l10n_info()[["UTF-8"]])) {
  for (loc in c("C.UTF-8", "C.utf8", "en_US.UTF-8", "en_GB.UTF-8"))
    if (nzchar(suppressWarnings(Sys.setlocale("LC_CTYPE", loc)))) break
}

APP_DIR <- normalizePath(".")   # app folder (fixed at start-up)

# parse(encoding = "UTF-8") instead of source(): works even when the server
# runs with a non-UTF-8 locale (e.g. LANG=C), where source() would fail
load_file <- function(f) eval(parse(file.path(APP_DIR, f), encoding = "UTF-8"), envir = parent.frame())
load_file("R/calculations.R")
load_file("R/plot.R")

time_field <- function(id, label, value = "") textInput(id, label, value, placeholder = "HH:MM")

ui <- page_sidebar(
  title = "mGFR iohexol – calculation and report",
  theme = bs_theme(bootswatch = "flatly"),
  sidebar = sidebar(
    width = 430,
    accordion(
      open = c("Patient", "Laboratory", "Iohexol samples"),
      accordion_panel("Patient",
        textInput("request_id", "Request no."),
        layout_columns(textInput("surname", "Surname"), textInput("first_name", "First name")),
        layout_columns(
          radioButtons("sex", "Sex", c("M", "F"), inline = TRUE, selected = character(0)),
          suppressWarnings(dateInput("birth_date", "Date of birth", value = NA, format = "yyyy-mm-dd",
                    language = "en", startview = "decade"))),
        layout_columns(numericInput("weight", "Weight (kg)", NA, min = 1, step = 0.1),
                       numericInput("height", "Height (cm)", NA, min = 30, step = 1)),
        textAreaInput("clinical_question", "Clinical question", rows = 2)
      ),
      accordion_panel("Laboratory",
        dateInput("sample_date", "Sampling date", value = Sys.Date(),
                  format = "yyyy-mm-dd", language = "en"),
        layout_columns(numericInput("scr", "Creatinine (mg/dL)", NA, min = 0, step = 0.01),
                       numericInput("scys", "Cystatin C (mg/L)", NA, min = 0, step = 0.01))
      ),
      accordion_panel("Iohexol samples",
        layout_columns(
          numericInput("dose_ug", "Injected dose (µg)", DEFAULT_DOSE_UG, min = 0, step = 1000),
          time_field("t0", "T0 injection")),
        helpText("Default 3,235,000 µg = 5 mL Omnipaque 300. Enter 2 to 5 samples; empty rows are ignored."),
        lapply(1:5, function(i) layout_columns(
          time_field(paste0("time", i), paste0("T", i, " time")),
          numericInput(paste0("conc", i), paste0("IOHEX", i, " (mg/L)"), NA, min = 0, step = 0.01)))
      )
    ),
    actionButton("clear", "Clear form", icon = icon("eraser"), class = "btn-outline-secondary")
  ),

  layout_columns(
    col_widths = c(12, 7, 5, 12),
    uiOutput("alerts_box"),
    card(card_header("Results"), tableOutput("results_tab")),
    card(card_header("Decay curve"), plotOutput("plot", height = 300)),
    card(card_header("Sample details and calculation steps"), tableOutput("points_tab"),
         uiOutput("steps"))
  ),
  card(
    card_header("Report"),
    downloadButton("report_html", "Download HTML report", class = "btn-primary"),
    helpText("The HTML report opens in any browser and can be printed to PDF from there.")
  )
)

server <- function(input, output, session) {

  # ---- clear form -----------------------------------------------------------
  fill <- function(e) {
    updateTextInput(session, "request_id", value = e$request_id %||% "")
    updateTextInput(session, "surname", value = e$surname %||% "")
    updateTextInput(session, "first_name", value = e$first_name %||% "")
    updateRadioButtons(session, "sex", selected = e$sex %||% character(0))
    suppressWarnings(updateDateInput(session, "birth_date", value = e$birth_date %||% NA))
    updateDateInput(session, "sample_date", value = e$sample_date %||% Sys.Date())
    updateNumericInput(session, "weight", value = e$weight %||% NA)
    updateNumericInput(session, "height", value = e$height %||% NA)
    updateNumericInput(session, "scr", value = e$scr %||% NA)
    updateNumericInput(session, "scys", value = e$scys %||% NA)
    updateNumericInput(session, "dose_ug", value = e$dose_ug %||% DEFAULT_DOSE_UG)
    updateTextInput(session, "t0", value = e$t0 %||% "")
    updateTextAreaInput(session, "clinical_question", value = e$clinical_question %||% "")
    for (i in 1:5) {
      tm <- if (is.null(e$times)) NA else e$times[i]
      cc <- if (is.null(e$conc)) NA else e$conc[i]
      updateTextInput(session, paste0("time", i), value = if (is.na(tm)) "" else tm)
      updateNumericInput(session, paste0("conc", i), value = cc)
    }
  }
  observeEvent(input$clear, {
    fill(list())
  })

  # ---- inputs collected in a list -------------------------------------------
  data_in <- reactive({
    nn <- function(x) if (is.null(x) || length(x) == 0) NA else x
    list(
      request_id = input$request_id, surname = input$surname, first_name = input$first_name,
      sex = nn(input$sex), birth_date = nn(input$birth_date),
      sample_date = nn(input$sample_date),
      weight = nn(input$weight), height = nn(input$height),
      scr = nn(input$scr), scys = nn(input$scys),
      dose_ug = nn(input$dose_ug), t0 = input$t0,
      times = vapply(1:5, function(i) input[[paste0("time", i)]] %||% "", ""),
      conc = vapply(1:5, function(i) as.numeric(nn(input[[paste0("conc", i)]])), 0),
      clinical_question = input$clinical_question
    )
  })
  res <- reactive(calc_all(data_in()))

  # ---- on-screen output -----------------------------------------------------
  output$alerts_box <- renderUI({
    r <- res(); err <- c(r$mgfr$errors, r$egfr_errors); wrn <- c(r$mgfr$warnings, r$egfr_warnings)
    if (is.na(r$age)) err <- c(err, "Age cannot be calculated: enter date of birth and sampling date.")
    tagList(
      if (length(err)) div(class = "alert alert-danger", HTML(paste(err, collapse = "<br>"))),
      if (length(wrn)) div(class = "alert alert-warning", HTML(paste(wrn, collapse = "<br>")))
    )
  })

  output$results_tab <- renderTable({
    r <- res(); t <- results_table(r)
    t$`KDIGO category` <- c("", vapply(t$Value[-1], kdigo_category, ""))
    t$`KDIGO category`[is.na(t$`KDIGO category`)] <- ""
    t$Value <- fmt(t$Value)
    t
  }, striped = TRUE, align = "lrll")

  output$plot <- renderPlot(decay_plot(res()$mgfr))

  output$points_tab <- renderTable({
    p <- res()$mgfr$points
    data.frame(Sample = p$sample, Time = p$time,
               `Min from T0` = fmt(p$t_min, 0), `mg/L` = fmt(p$conc, 2), `µmol/L` = fmt(p$conc_umol, 2),
               `ln C` = fmt(p$ln_conc, 4), Used = ifelse(p$used, "yes", "no"),
               check.names = FALSE)
  }, striped = TRUE, align = "llrrrrc")

  output$steps <- renderUI({
    r <- res(); mg <- r$mgfr
    if (is.null(mg$c0)) return(NULL)
    tags$ul(
      tags$li(sprintf("Age %s years · BSA %s m²", fmt(r$age, 0), fmt(r$bsa, 3))),
      tags$li(sprintf("Samples used: %d%s", mg$n_points,
                      if (is.na(mg$r2)) "" else sprintf(" · R² = %s", fmt(mg$r2, 4)))),
      tags$li(sprintf("C0 = %s mg/L · k = %s min⁻¹ · half-life %s min",
                      fmt(mg$c0, 2), formatC(mg$k, format = "e", digits = 4), fmt(mg$half_life_min, 0))),
      tags$li(sprintf("AUC = %s mg·min/L · CL = %s mL/min",
                      fmt(mg$auc, 0), fmt(mg$cl, 1))),
      tags$li(sprintf("Brøchner-Mortensen on absolute CL: %s mL/min → normalised: %s mL/min/1.73 m²",
                      fmt(mg$gfr_abs, 1), fmt(mg$gfr_norm, 1)))
    )
  })

  # ---- report ---------------------------------------------------------------
  file_name <- function(ext) {
    d <- data_in()
    base <- paste("mGFR", d$surname, d$first_name, format(as_date_safe(d$sample_date), "%Y%m%d"), sep = "_")
    paste0(gsub("[^A-Za-z0-9_-]+", "", gsub(" ", "_", base)), ".", ext)
  }
  render_report <- function(format, file) {
    id <- showNotification("Generating report…", duration = NULL)
    on.exit(removeNotification(id))
    tmp <- tempfile("report_"); dir.create(tmp)
    file.copy(file.path(APP_DIR, "report.Rmd"), tmp)
    out <- rmarkdown::render(file.path(tmp, "report.Rmd"), output_format = format,
                             params = list(inp = data_in(), app_dir = APP_DIR),
                             envir = new.env(), quiet = TRUE)
    file.copy(out, file, overwrite = TRUE)
  }
  output$report_html <- downloadHandler(function() file_name("html"),
                                        function(file) render_report("html_document", file))
}

shinyApp(ui, server)
